package com.witchersbestiary.signs;
import java.util.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.entity.*;import net.minecraft.entity.mob.*;import net.minecraft.entity.passive.*;import net.minecraft.entity.effect.*;import net.minecraft.entity.damage.*;import net.minecraft.registry.*;import net.minecraft.registry.tag.DamageTypeTags;import net.minecraft.util.*;import net.minecraft.util.math.*;import net.minecraft.particle.*;import net.minecraft.sound.*;import net.minecraft.text.Text;import net.fabricmc.fabric.api.networking.v1.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;
public final class SignManager {
 public static final RegistryKey<DamageType> DAMAGE=RegistryKey.of(RegistryKeys.DAMAGE_TYPE,Identifier.of("witchersbestiary:sign"));
 public static final RegistryKey<DamageType> FIRE=RegistryKey.of(RegistryKeys.DAMAGE_TYPE,Identifier.of("witchersbestiary:igni"));
 public static final net.minecraft.registry.tag.TagKey<EntityType<?>> CONTROL_IMMUNE=net.minecraft.registry.tag.TagKey.of(RegistryKeys.ENTITY_TYPE,Identifier.of("witchersbestiary:control_immune"));
 public static boolean signDamage(DamageSource source){return source.isOf(DAMAGE)||source.isOf(FIRE);}
 private record Burn(UUID owner,RegistryKey<net.minecraft.world.World> dimension,long until){}
 private static final Map<UUID,Burn> BURNS=new HashMap<>();
 public static DamageSource resolveBurn(LivingEntity victim,DamageSource source){if(!source.isOf(DamageTypes.ON_FIRE)||!(victim.getWorld() instanceof ServerWorld w))return source;var burn=BURNS.get(victim.getUuid());if(burn==null||burn.until<w.getTime())return source;var owner=w.getServer().getPlayerManager().getPlayer(burn.owner);if(owner==null||owner.getWorld()!=w||!allowed(owner)||!enemy(owner,victim)){victim.extinguish();BURNS.remove(victim.getUuid());return null;}return new DamageSource(w.getRegistryManager().get(RegistryKeys.DAMAGE_TYPE).entryOf(FIRE),owner);}
 private static void clearBurns(net.minecraft.server.MinecraftServer server,UUID owner){var it=BURNS.entrySet().iterator();while(it.hasNext()){var entry=it.next();var burn=entry.getValue();if(owner==null||owner.equals(burn.owner)){var w=server.getWorld(burn.dimension);if(w!=null&&w.getEntity(entry.getKey()) instanceof LivingEntity e)e.extinguish();it.remove();}}}
 private static final Map<UUID,Runtime> ACTIVE=new HashMap<>();private static final Map<UUID,Long> CALM=new HashMap<>(),EXPOSED=new HashMap<>();
 public static boolean yrdenExposed(LivingEntity e){return EXPOSED.getOrDefault(e.getUuid(),Long.MIN_VALUE)>e.getWorld().getTime();}
 private static final class Runtime {UUID session=UUID.randomUUID();long sequence=-1;int requestWindow,requests;float shield;int shieldTicks,trapTicks;Vec3d trap;RegistryKey<net.minecraft.world.World> dimension;}
 private static Runtime runtime(ServerPlayerEntity p){var r=ACTIVE.computeIfAbsent(p.getUuid(),k->new Runtime());var dimension=p.getWorld().getRegistryKey();if(r.dimension!=null&&r.dimension!=dimension){r.shield=0;r.shieldTicks=0;r.trapTicks=0;r.trap=null;clearBurns(p.getServer(),p.getUuid());}r.dimension=dimension;return r;}
 public static SignPlayerState state(ServerPlayerEntity p){return SignLedger.get(p.getServer()).player(p.getUuid());}
 public static boolean calmed(LivingEntity e){Long until=CALM.get(e.getUuid());return until!=null&&until>e.getWorld().getTime();}
 public static boolean allowed(ServerPlayerEntity p){return p.isAlive()&&!p.isSpectator()&&!com.witchersbestiary.fist.FistFights.busy(p);}
 /** Hostility is a relationship/classification, never a mod-specific target whitelist. */
 public static boolean enemy(ServerPlayerEntity p,LivingEntity e){
  if(e==p||!e.isAlive()||e.getWorld()!=p.getWorld()||e.isInvulnerable()||p.isTeammate(e)||e.isTeammate(p)||com.witchersbestiary.fist.FistFights.busy(e)||e instanceof net.minecraft.village.Merchant||e instanceof net.minecraft.entity.Ownable owned&&owned.getOwner() instanceof net.minecraft.entity.player.PlayerEntity||e instanceof TameableEntity pet&&pet.isTamed()||e instanceof AbstractHorseEntity horse&&horse.isTame()||e instanceof PassiveEntity&&(!(e instanceof MobEntity mob)||mob.getTarget()!=p)||e instanceof net.minecraft.entity.decoration.ArmorStandEntity)return false;
  if(e instanceof net.minecraft.entity.player.PlayerEntity other)return !other.isCreative()&&!other.isSpectator()&&p.getServer().isPvpEnabled()&&p.shouldDamagePlayer(other);
  boolean provoked=e.getAttacker()==p||e instanceof MobEntity m&&m.getTarget()==p;
  if(e instanceof Angerable angry)return provoked||angry.shouldAngerAt(p);
  if(e instanceof PiglinEntity)return provoked;
  return provoked||e instanceof Monster||e.getType().getSpawnGroup()==SpawnGroup.MONSTER||e instanceof com.witchersbestiary.combat.CategorizedMonster;
 }
 public static boolean controlSupported(LivingEntity e){return e instanceof MobEntity m&&!m.isAiDisabled()&&!e.getType().isIn(CONTROL_IMMUNE );}
 private static boolean large(LivingEntity e){return e.getWidth()>1.5||e.getMaxHealth()>=200;}
 private record TrapHit(RegistryKey<net.minecraft.world.World> dimension,long next){}
 private static final Map<UUID,TrapHit> TRAP_HITS=new HashMap<>();

 public static void intent(ServerPlayerEntity p,SignPackets.Intent packet){var r=runtime(p);int tick=p.getServer().getTicks();if(tick-r.requestWindow>=20){r.requests=0;r.requestWindow=tick;}if(++r.requests>8)return;if(!p.getWorld().getRegistryKey().getValue().toString().equals(packet.dimension())||!r.session.equals(packet.session())||packet.sequence()<=r.sequence)return;r.sequence=packet.sequence();var sign=SignType.byIndex(packet.sign());if(packet.action()==0){if(sign!=null&&state(p).select(sign))SignLedger.get(p.getServer()).markDirty();}else if(packet.action()==1)cast(p,packet.sequence());else if(packet.action()==2&&sign!=null)learnFromBestiary(p,sign);sync(p);}
 public static boolean learnFromBestiary(ServerPlayerEntity p,SignType sign){boolean book=false;for(int slot=0;slot<p.getInventory().size();slot++)if(p.getInventory().getStack(slot).isOf(com.witchersbestiary.registry.ModItems.BESTIARY)){book=true;break;}if(!book||!p.isAlive()||p.isSpectator())return false;if(state(p).learn(sign)){SignLedger.get(p.getServer()).markDirty();}sync(p);return true;}
 public static boolean cast(ServerPlayerEntity p,long request){if(!allowed(p)){p.sendMessage(Text.translatable("sign.witchersbestiary.unavailable"),true);return false;}var s=state(p);var sign=s.selected();var w=p.getServerWorld();var r=runtime(p);if(sign==SignType.QUEN&&r.shieldTicks>0&&r.shield>0)return false;var origin=p.getEyePos();var look=p.getRotationVec(1);var targets=w.getEntitiesByClass(LivingEntity.class,p.getBoundingBox().expand(sign.range),e->enemy(p,e)&&(sign!=SignType.AXII||controlSupported(e))&&p.canSee(e)&&e.getEyePos().distanceTo(origin)<=sign.range&&e.getEyePos().subtract(origin).normalize().dotProduct(look)>=Math.cos(Math.toRadians(sign==SignType.AXII?12:30)));targets.sort(Comparator.comparingDouble(p::squaredDistanceTo));if(sign==SignType.AXII&&(targets.isEmpty()||!(targets.getFirst() instanceof MobEntity)))return false;
 if(sign==SignType.AXII){Long until=CALM.get(targets.getFirst().getUuid());if(until!=null&&until+80>w.getTime())return false;}
 Vec3d trap=p.getPos();if(sign==SignType.YRDEN){var pos=p.getBlockPos();if(!w.isChunkLoaded(pos)||!w.getBlockState(pos).getCollisionShape(w,pos).isEmpty()||!w.getBlockState(pos.down()).isSideSolidFullSquare(w,pos.down(),Direction.UP))return false;}
 if(!s.commit(sign,request))return false;SignLedger.get(p.getServer()).markDirty();r.dimension=w.getRegistryKey();p.swingHand(Hand.OFF_HAND,true);var damage=new DamageSource(w.getRegistryManager().get(RegistryKeys.DAMAGE_TYPE).entryOf(sign==SignType.IGNI?FIRE:DAMAGE),p);
 switch(sign){case IGNI,AARD->{for(var target:targets.stream().limit(12).toList()){if(sign==SignType.IGNI&&(target.isFireImmune()||target.hasStatusEffect(StatusEffects.FIRE_RESISTANCE)))continue;if(target.damage(damage,sign==SignType.IGNI?4.8f:1.15f)){if(sign==SignType.IGNI&&!target.isFireImmune()){target.setOnFireFor(3);BURNS.put(target.getUuid(),new Burn(p.getUuid(),w.getRegistryKey(),w.getTime()+60));}if(sign==SignType.AARD){double factor=large(target)?.3:1;target.takeKnockback(.85*factor,p.getX()-target.getX(),p.getZ()-target.getZ());target.velocityModified=true;}}}for(int i=1;i<=12;i++){var at=origin.add(look.multiply(i*sign.range/12));w.spawnParticles(sign==SignType.IGNI?ParticleTypes.FLAME:ParticleTypes.CLOUD,at.x,at.y,at.z,2,.12,.12,.12,.015);}}
 case QUEN->{r.shield=10;r.shieldTicks=240;burst(w,p.getPos().add(0,1,0),sign,16);}
 case YRDEN->{r.trap=trap;r.trapTicks=200;r.dimension=w.getRegistryKey();}
 case AXII->{var target=(MobEntity)targets.getFirst();long now=w.getTime();Long until=CALM.get(target.getUuid());if(until==null||until+80<=now){CALM.put(target.getUuid(),now+(large(target)?30:80));target.setTarget(null);target.getNavigation().stop();burst(w,target.getEyePos(),sign,6);}}
 }w.playSound(null,p.getBlockPos(),switch(sign){case IGNI->SoundEvents.ITEM_FIRECHARGE_USE;case AARD->SoundEvents.ENTITY_BREEZE_SHOOT;case QUEN->SoundEvents.BLOCK_AMETHYST_BLOCK_CHIME;case YRDEN->SoundEvents.BLOCK_AMETHYST_BLOCK_RESONATE;case AXII->SoundEvents.BLOCK_BEACON_AMBIENT;},SoundCategory.PLAYERS,.45f,1.15f);sync(p);return true;}
 private static void burst(ServerWorld w,Vec3d at,SignType sign,int count){int rgb=sign.color;w.spawnParticles(new DustParticleEffect(new org.joml.Vector3f(((rgb>>16)&255)/255f,((rgb>>8)&255)/255f,(rgb&255)/255f),.9f),at.x,at.y,at.z,count,.45,.5,.45,.01);}
 public static float protect(LivingEntity victim,DamageSource source,float amount){if(!(victim instanceof ServerPlayerEntity p)||!allowed(p)||!Float.isFinite(amount)||amount<=0||p.isInvulnerableTo(source)||p.blockedByShield(source)||source.isIn(DamageTypeTags.BYPASSES_INVULNERABILITY))return amount;var r=runtime(p);if(r.shieldTicks<=0||r.shield<=0)return amount;float taken=Math.min(r.shield,amount);r.shield-=taken;burst(p.getServerWorld(),p.getPos().add(0,1,0),SignType.QUEN,r.shield<=0?12:4);sync(p);return amount-taken;}
 public static void sync(ServerPlayerEntity p){if(!ServerPlayNetworking.canSend(p,SignPackets.View.ID))return;var s=state(p);var r=runtime(p);ServerPlayNetworking.send(p,new SignPackets.View(r.session,s.learned(),s.selected().ordinal(),(float)s.concentration(),s.cooldown(s.selected()),r.shield,r.shieldTicks,r.trapTicks,s.cooldown(SignType.IGNI),s.cooldown(SignType.AARD),s.cooldown(SignType.QUEN),s.cooldown(SignType.YRDEN),s.cooldown(SignType.AXII)));}
 public static void initialize(){SignPackets.initialize();net.fabricmc.fabric.api.entity.event.v1.ServerPlayerEvents.AFTER_RESPAWN.register((oldPlayer,newPlayer,alive)->{ACTIVE.remove(newPlayer.getUuid());clearBurns(newPlayer.getServer(),newPlayer.getUuid());state(newPlayer).resetProtocol();sync(newPlayer);});net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents.AFTER_DEATH.register((entity,source)->{if(entity instanceof ServerPlayerEntity player){ACTIVE.remove(player.getUuid());clearBurns(player.getServer(),player.getUuid());}});ServerPlayConnectionEvents.JOIN.register((h,sender,server)->{state(h.player).resetProtocol();ACTIVE.remove(h.player.getUuid());sync(h.player);});ServerPlayConnectionEvents.DISCONNECT.register((h,s)->{ACTIVE.remove(h.player.getUuid());clearBurns(s,h.player.getUuid());SignLedger.get(s).markDirty();});ServerLifecycleEvents.SERVER_STOPPING.register(server->clearBurns(server,null));ServerLifecycleEvents.SERVER_STOPPED.register(s->{ACTIVE.clear();CALM.clear();EXPOSED.clear();BURNS.clear();TRAP_HITS.clear();});ServerTickEvents.END_SERVER_TICK.register(server->{for(var p:server.getPlayerManager().getPlayerList()){var r=runtime(p);state(p).tick();if(!allowed(p)||r.dimension!=null&&r.dimension!=p.getWorld().getRegistryKey()){r.shield=0;r.shieldTicks=0;r.trapTicks=0;}if(r.shieldTicks>0&&--r.shieldTicks==0)r.shield=0;if(r.trapTicks>0){r.trapTicks--;if(server.getTicks()%10==0){var w=p.getServerWorld();for(var e:w.getEntitiesByClass(LivingEntity.class,new Box(r.trap.add(-3,-1,-3),r.trap.add(3,3,3)),e->enemy(p,e)&&e.squaredDistanceTo(r.trap)<=9&&p.canSee(e)).stream().limit(16).toList()){if(!e.getType().isIn(CONTROL_IMMUNE))e.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,15,large(e)?0:1));var hit=TRAP_HITS.get(e.getUuid());if(hit==null||hit.dimension()!=w.getRegistryKey()||hit.next()<=w.getTime()){TRAP_HITS.put(e.getUuid(),new TrapHit(w.getRegistryKey(),w.getTime()+40));e.damage(new DamageSource(w.getRegistryManager().get(RegistryKeys.DAMAGE_TYPE).entryOf(DAMAGE),p),1);}if(e instanceof com.witchersbestiary.combat.CategorizedMonster monster&&monster.getMonsterCategory()==com.witchersbestiary.combat.MonsterCategory.SPECTER)EXPOSED.put(e.getUuid(),w.getTime()+15);}for(int i=0;i<24;i++){double a=i*Math.PI/12;burst(w,r.trap.add(Math.cos(a)*3,.1,Math.sin(a)*3),SignType.YRDEN,1);}}}if(server.getTicks()%10==0)sync(p);}if(server.getTicks()%20==0){SignLedger.get(server).markDirty();TRAP_HITS.entrySet().removeIf(e->{var world=server.getWorld(e.getValue().dimension());return world==null||e.getValue().next()+40<world.getTime();});BURNS.entrySet().removeIf(e->{var world=server.getWorld(e.getValue().dimension);return world==null||e.getValue().until<world.getTime();});EXPOSED.entrySet().removeIf(e->e.getValue()<server.getOverworld().getTime());CALM.entrySet().removeIf(e->e.getValue()+80<server.getOverworld().getTime());}});}
}
